class ComplexNumber {double a,b;ComplexNumber(double a,double b){this.a=a;this.b=b;}double getReal(){return a;}double getImaginary(){return b;}double abs(){return Math.hypot(a,b);}ComplexNumber add(ComplexNumber z){return new ComplexNumber(a+z.a,b+z.b);}ComplexNumber subtract(ComplexNumber z){return new ComplexNumber(a-z.a,b-z.b);}ComplexNumber multiply(ComplexNumber z){return new ComplexNumber(a*z.a-b*z.b,a*z.b+b*z.a);}ComplexNumber divide(ComplexNumber z){double d=z.a*z.a+z.b*z.b;return new ComplexNumber((a*z.a+b*z.b)/d,(b*z.a-a*z.b)/d);}ComplexNumber conjugate(){return new ComplexNumber(a,-b);}ComplexNumber exponentialOf(){return new ComplexNumber(Math.exp(a)*Math.cos(b),Math.exp(a)*Math.sin(b));}}